-- 005_institutions_real_data.sql
-- Реални данни за институциите (проучване от 07.10.2026, файл „Институции_Сливен.xlsx“).
-- Контактите са само за справка: real_send остава false, писмата отиват на демо имейл.

-- Тип на институцията
create type public.institution_kind as enum (
  'internal_unit',         -- вътрешно звено на общината
  'municipal_enterprise',  -- общинско предприятие
  'municipal_company',     -- общинско дружество
  'contractor',            -- външен изпълнител на общината
  'external'               -- външна институция или дружество
);

-- Степен на потвърждение на контакта
create type public.verification_status as enum (
  'confirmed',  -- потвърдено от официален източник
  'partial',    -- частично потвърдено
  'not_found'   -- не е намерено
);

alter table public.institutions
  add column kind                public.institution_kind,
  add column responsibility      text,
  add column phone               text,
  add column address             text,
  add column source              text,
  add column verification_status public.verification_status not null default 'not_found',
  add column verified_on         date,
  add column verification_note   text;       -- какво още трябва да се провери

-- 1) Съществуващите 18 институции от 003: сменяме имената и попълваме данните.
--    Редовете запазват id, затова връзките от подкатегориите не се развалят.
update public.institutions i
set name                = v.new_name,
    kind                = v.kind::public.institution_kind,
    responsibility      = v.responsibility,
    email               = v.email,
    phone               = v.phone,
    address             = v.address,
    source              = v.source,
    verification_status = v.st::public.verification_status,
