-- 2) Три нови записа, които ги няма в 003
insert into public.institutions
  (name, kind, responsibility, email, phone, address, source,
   verification_status, verified_on, verification_note, note, active)
select new_name, kind::public.institution_kind, responsibility, email, phone, address, source,
       st::public.verification_status, date '2026-10-07', vnote, note, active
from (values
  (null, 'Община Сливен – Отдел „Обществени сгради“', 'internal_unit', 'Общински сгради; съдейства на дружествата за ток, топло и газ', 'signali@sliven.bg', '044/663 066', 'бул. „Цар Освободител“ 1', 'Устройствен правилник на ОА Сливен', 'confirmed', null, null, true),
  (null, 'Община Сливен – Дирекция „Общинска собственост и икономика“', 'internal_unit', 'Неправомерно ползване на общински имоти, реклами и преместваеми обекти, търговски обекти, обществен ред (проверки), такси и обществен транспорт', 'signali@sliven.bg', '044/663 066', 'бул. „Цар Освободител“ 1', 'Устройствен правилник на ОА Сливен', 'confirmed', null, null, true),
  (null, 'Кметства и кметски наместничества', 'internal_unit', 'Сигнали в селата; допълнително известяване при сигнал в населено място', 'signali@sliven.bg', '044/663 066 (общ дежурен)', 'населени места на общината', 'Устройствен правилник на ОА Сливен', 'confirmed', 'Да се съберат имейлите на отделните кметства.', '38 кметства и 6 наместничества. Не се ползва в MVP (известяване на кметства е извън MVP).', false)
) as v(old_name, new_name, kind, responsibility, email, phone, address, source, st, vnote, note, active);

-- Защита: очакваме точно 21 институции и нито една без тип
do $$
begin
  if (select count(*) from public.institutions) <> 21 then
    raise exception 'Очаквани 21 институции, намерени %', (select count(*) from public.institutions);
  end if;
  if exists (select 1 from public.institutions where kind is null) then
    raise exception 'Има институция без тип; провери имената от 003';
  end if;
end $$;

alter table public.institutions alter column kind set not null;
